-- Development only; no jobs are authorized by migration.
BEGIN;
alter table faro_private.social_credentials add column revision uuid not null default gen_random_uuid(), add column refresh_owner uuid;
create function faro_private.credential_revision() returns trigger language plpgsql set search_path=pg_catalog as $$ begin new.revision=gen_random_uuid(); new.refresh_owner=null; return new; end $$;
revoke all on function faro_private.credential_revision() from public;
create trigger credential_revision before update of ciphertext on faro_private.social_credentials for each row execute function faro_private.credential_revision();
create function faro_private.job_context(jid uuid,lid uuid) returns jsonb language sql security definer set search_path=pg_catalog as $$ select jsonb_build_object('connectionId',c.id,'brandId',c.brand_id,'provider',c.provider,'externalId',c.external_account_id,'status',c.status,'accountEnabled',a.enabled,'ciphertext',s.ciphertext,'revision',s.revision,'refreshOwner',s.refresh_owner,'media',case when m.id is not null then jsonb_build_object('id',m.id,'path',m.storage_path,'mime',m.mime_type,'bytes',m.byte_size) else null end) from faro_private.publication_jobs j join faro.connections c on c.id=j.connection_id and c.brand_id=j.brand_id join faro.brands b on b.id=j.brand_id join faro.workspaces w on w.id=b.workspace_id join faro.accounts a on a.id=w.owner_id join faro_private.social_credentials s on s.connection_id=c.id left join faro.media m on m.id::text=j.payload->>'media_id' and m.brand_id=j.brand_id and m.upload_state='ready' and m.storage_path=j.payload->>'storage_path' and m.mime_type=j.payload->>'mime_type' and m.byte_size::text=j.payload->>'byte_size' where j.id=jid and j.lease_id=lid and j.lease_expires_at>now() and j.status='processing' and j.authorized_at is not null and j.payload->'consent'='true'::jsonb and a.enabled and c.status='connected' and c.provider=j.payload->>'provider' and (j.payload->>'media_id' is null or m.id is not null) $$;
revoke all on function faro_private.job_context(uuid,uuid) from public;
grant execute on function faro_private.job_context(uuid,uuid) to faro_worker;
create function faro_private.reserve_refresh(jid uuid,lid uuid,rev uuid) returns boolean language plpgsql security definer set search_path=pg_catalog as $$ declare ctx jsonb; n integer; begin ctx:=faro_private.job_context(jid,lid); if ctx is null or ctx->>'provider' not in ('youtube','tiktok') then return false; end if; update faro_private.social_credentials set refresh_owner=lid where connection_id=(ctx->>'connectionId')::uuid and revision=rev and refresh_owner is null; get diagnostics n=row_count; return n=1; end $$;
revoke all on function faro_private.reserve_refresh(uuid,uuid,uuid) from public;
grant execute on function faro_private.reserve_refresh(uuid,uuid,uuid) to faro_worker;
create function faro_private.save_refresh(jid uuid,lid uuid,rev uuid,encrypted text) returns boolean language plpgsql security definer set search_path=pg_catalog as $$ declare ctx jsonb; n integer; begin ctx:=faro_private.job_context(jid,lid); if ctx is null or ctx->>'provider' not in ('youtube','tiktok') or length(encrypted) not between 20 and 65536 then return false; end if; update faro_private.social_credentials set ciphertext=encrypted,updated_at=now() where connection_id=(ctx->>'connectionId')::uuid and revision=rev and refresh_owner=lid; get diagnostics n=row_count; return n=1; end $$;
revoke all on function faro_private.save_refresh(uuid,uuid,uuid,text) from public;
grant execute on function faro_private.save_refresh(uuid,uuid,uuid,text) to faro_worker;
create role faro_delivery_media nologin nobypassrls;
grant faro_delivery_media to current_user;
grant usage on schema faro_private to faro_delivery_media;
create function faro_private.delivery_file(jid uuid,mid uuid,pr text) returns jsonb language sql security definer set search_path=pg_catalog as $$ select jsonb_build_object('path',m.storage_path,'mime',m.mime_type,'bytes',m.byte_size) from faro_private.publication_jobs j join faro.connections c on c.id=j.connection_id and c.brand_id=j.brand_id join faro.brands b on b.id=j.brand_id join faro.workspaces w on w.id=b.workspace_id join faro.accounts a on a.id=w.owner_id join faro.media m on m.id=mid and m.brand_id=j.brand_id where j.id=jid and j.authorized_at is not null and j.payload->'consent'='true'::jsonb and (j.status='awaiting' or (j.status='processing' and j.lease_expires_at>now())) and a.enabled and c.status='connected' and c.provider=pr and pr in ('instagram','tiktok') and j.payload->>'provider'=pr and j.payload->>'media_id'=mid::text and m.upload_state='ready' and m.storage_path=j.payload->>'storage_path' and m.mime_type=j.payload->>'mime_type' and m.byte_size::text=j.payload->>'byte_size' $$;
revoke all on function faro_private.delivery_file(uuid,uuid,text) from public;
grant execute on function faro_private.delivery_file(uuid,uuid,text) to faro_delivery_media;
COMMIT;
